package ca.teamdman.sfm.gametest.tests.cable.tunnelled;

import ca.teamdman.sfm.common.capability.SFMWellKnownCapabilities;
import ca.teamdman.sfm.common.registry.registration.SFMBlocks;
import ca.teamdman.sfm.gametest.SFMGameTest;
import ca.teamdman.sfm.gametest.SFMGameTestDefinition;
import ca.teamdman.sfm.gametest.SFMGameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.capabilities.BlockCapabilityCache;

import java.util.concurrent.atomic.AtomicInteger;

/**
 * Adapted from local relay experiment c9cf6261ec2dada8d8c9c7bd7679d3f590a2c8ed.
 * Mutual position listeners must drain once per wave, including after caches re-arm.
 * This does not establish the broader Mekanism reactor/relog scenario.
 */
@SFMGameTest
public class TunnelledCapabilityRelayCycleGameTest extends SFMGameTestDefinition {
    private static final BlockPos A = new BlockPos(3, 2, 3);
    private static final BlockPos B = A.east();

    @Override
    public String template() {
        return "7x4x7";
    }

    @Override
    public int maxTicks() {
        return 30;
    }

    @Override
    public void run(SFMGameTestHelper helper) {
        helper.setBlock(A.west(), Blocks.AIR);
        helper.setBlock(A, SFMBlocks.TUNNELLED_CABLE.get());
        helper.setBlock(B, SFMBlocks.TUNNELLED_CABLE.get());
        helper.setBlock(B.east(), Blocks.AIR);

        AtomicInteger aNotifications = new AtomicInteger();
        AtomicInteger bNotifications = new AtomicInteger();
        var aCache = BlockCapabilityCache.create(
                SFMWellKnownCapabilities.ITEM_HANDLER.capabilityKind(), helper.getLevel(),
                helper.absolutePos(A), Direction.WEST, () -> true, aNotifications::incrementAndGet);
        var bCache = BlockCapabilityCache.create(
                SFMWellKnownCapabilities.ITEM_HANDLER.capabilityKind(), helper.getLevel(),
                helper.absolutePos(B), Direction.EAST, () -> true, bNotifications::incrementAndGet);
        helper.assertTrue(aCache.getCapability() == null, "A should forward into B's empty east endpoint");
        helper.assertTrue(bCache.getCapability() == null, "B should forward into A's empty west endpoint");

        helper.runAfterDelay(5, () -> {
            aCache.getCapability();
            bCache.getCapability();
            aNotifications.set(0);
            bNotifications.set(0);
            helper.getLevel().invalidateCapabilities(helper.absolutePos(A));
        });
        helper.runAfterDelay(10, () -> {
            helper.assertTrue(aNotifications.get() == 1,
                    "A should receive its one direct notification, got " + aNotifications.get());
            helper.assertTrue(bNotifications.get() == 1,
                    "B should receive exactly one relayed notification, got " + bNotifications.get());
            aCache.getCapability();
            bCache.getCapability();
        });
        helper.runAfterDelay(15, () -> {
            helper.assertTrue(aNotifications.get() == 1 && bNotifications.get() == 1,
                    "The first wave bounced between tunnels after caches re-armed");
            helper.getLevel().invalidateCapabilities(helper.absolutePos(A));
        });
        helper.runAfterDelay(20, () -> {
            helper.assertTrue(aNotifications.get() == 2,
                    "A should notify again in the second wave, got " + aNotifications.get());
            helper.assertTrue(bNotifications.get() == 2,
                    "B should notify exactly once in the second wave, got " + bNotifications.get());
            helper.succeed();
        });
    }
}
